/* ─── Design Tokens — Generated by Design Inspiration MCP ─────────────────
   Brand: #122B4E | Mode: light | 65 tokens
   ────────────────────────────────────────────────────────────────────────── */

:root {
  --color-bg: #FFFFFF;
  --color-bg-secondary: #F8F9FA;
  --color-bg-tertiary: #F1F3F5;
  --color-surface: #FFFFFF;
  --color-border: rgba(0,0,0,0.08);
  --color-border-strong: rgba(0,0,0,0.15);
  --color-text: #0A0A0F;
  --color-text-secondary: #4A4A5A;
  --color-text-tertiary: #8A8A9A;
  --color-brand: #122B4E;
  --color-brand-light: rgb(89, 107, 131);
  --color-brand-dark: rgb(14, 34, 62);
  --color-brand-subtle: rgba(18, 43, 78, 0.08);
  --color-brand-border: rgba(18, 43, 78, 0.25);
  --space-0: 0px;
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 20px;
  --space-6: 24px;
  --space-8: 32px;
  --space-10: 40px;
  --space-12: 48px;
  --space-16: 64px;
  --space-20: 80px;
  --space-24: 96px;
  --space-32: 128px;
  --text-xs: 10px;
  --text-sm: 13px;
  --text-base: 16px;
  --text-lg: 20px;
  --text-xl: 25px;
  --text-2xl: 31px;
  --text-3xl: 39px;
  --text-4xl: 49px;
  --text-5xl: 61px;
  --shadow-xs: 0 1px 2px rgba(0,0,0,0.04);
  --shadow-sm: 0 2px 4px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 16px rgba(0,0,0,0.08), 0 2px 4px rgba(0,0,0,0.04);
  --shadow-lg: 0 8px 32px rgba(0,0,0,0.12), 0 4px 8px rgba(0,0,0,0.06);
  --shadow-xl: 0 20px 60px rgba(0,0,0,0.15), 0 8px 20px rgba(0,0,0,0.08);
  --shadow-2xl: 0 40px 80px rgba(0,0,0,0.2), 0 16px 40px rgba(0,0,0,0.1);
  --radius-xs: 2px;
  --radius-sm: 3px;
  --radius-md: 4px;
  --radius-lg: 6px;
  --radius-xl: 8px;
  --radius-2xl: 12px;
  --radius-full: 9999px;
  --duration-fast: 100ms;
  --duration-base: 150ms;
  --duration-slow: 250ms;
  --ease-default: cubic-bezier(0.2, 0, 0, 1);
  --ease-spring: cubic-bezier(0.34, 1.56, 0.64, 1);
  --ease-out: cubic-bezier(0, 0, 0.2, 1);
  --z-base: 0;
  --z-raised: 10;
  --z-dropdown: 100;
  --z-sticky: 200;
  --z-overlay: 300;
  --z-modal: 400;
  --z-toast: 500;
  --z-tooltip: 600;
  --z-max: 9999;
}

/* Dark mode override — add [data-theme="dark"] to <html> to toggle */
@media (prefers-color-scheme: dark) {
  :root {
    --color-bg: #0A0A0F;
    --color-bg-secondary: #111118;
    --color-text: #F5F5FF;
    --color-text-secondary: #9090AA;
    --color-border: rgba(255,255,255,0.08);
  }
}

usage_examples:
/* Card component using tokens */
.card {
  padding: var(--space-6);
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-border);
  background: var(--color-surface);
  box-shadow: var(--shadow-md);
  transition: box-shadow var(--duration-base) var(--ease-default);
}
.card:hover { box-shadow: var(--shadow-lg); }

/* Button using brand tokens */
.btn-primary {
  padding: var(--space-3) var(--space-6);
  border-radius: var(--radius-md);
  background: var(--color-brand);
  color: white;
  font-size: var(--text-sm);
  transition: background var(--duration-fast) var(--ease-default);
}
.btn-primary:hover { background: var(--color-brand-dark); }

/* Heading with type scale */
h1 { font-size: var(--text-4xl); letter-spacing: -0.04em; line-height: 1.05; }
h2 { font-size: var(--text-3xl); letter-spacing: -0.03em; line-height: 1.1; }
h3 { font-size: var(--text-xl); letter-spacing: -0.01em; line-height: 1.3; }
p  { font-size: var(--text-base); line-height: 1.7; color: var(--color-text-secondary); }

/* Z-index usage — use tokens, never raw numbers */
.navbar  { z-index: var(--z-sticky); }
.modal   { z-index: var(--z-modal); }
.toast   { z-index: var(--z-toast); }
.tooltip { z-index: var(--z-tooltip); }
